def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objects=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==2 and (ny,nx) not in seen:
              seen.add((ny,nx)); stack.append((ny,nx))
        if len(comp)==4:
          ys=[y for y,x in comp]; xs=[x for y,x in comp]
          rows={}
          for y,x in comp: rows[y]=rows.get(y,0)+1
          if sorted(rows.values())==[1,3]:
            objects.append((min(ys),min(xs),rows[min(ys)]==1))
    out=[[0]*6 for _ in range(3)]
    up=[o for o in objects if o[2]]; down=[o for o in objects if not o[2]]
    slots=[(0,0),(2,0),(0,2),(2,2)]
    for (r,c,_),(y,x) in zip(sorted(up),slots): out[y][x]=3
    for (r,c,_),(y,x) in zip(sorted(down),slots): out[y][x+3]=1
    return out
